  'advertiser_faq1_a': 'ಅಭಿಯಾನಗಳಿಗೆ ಹೋಗಿ ಮತ್ತು "ಅಭಿಯಾನವನ್ನು ರಚಿಸಿ" ಟ್ಯಾಪ್ ಮಾಡಿ. ಮೂಲ ಮಾಹಿತಿಯನ್ನು ನಮೂದಿಸಲು, ನಿಮ್ಮ 16:9 ಸೃಜನಾತ್ಮಕ ಸ್ವತ್ತನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಲು, ಗುರಿ ವಾಹನಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲು, ವೇಳಾಪಟ್ಟಿ ಮತ್ತು ಬಜೆಟ್ ಕಾನ್ಫಿಗರ್ ಮಾಡಲು ಮತ್ತು ಪರಿಶೀಲನೆಗಾಗಿ ಸಲ್ಲಿಸಲು ಹಂತ-ಹಂತದ ಸೆಟಪ್ ಅನುಸರಿಸಿ.',
  'advertiser_faq1_q': 'ಸಾರಿಗೆ ಜಾಹೀರಾತು ಅಭಿಯಾನವನ್ನು ರಚಿಸುವುದು ಮತ್ತು ಪ್ರಾರಂಭಿಸುವುದು ಹೇಗೆ?',
  'advertiser_faq2_a': 'ನಾವು MP4 (H.264), JPG, PNG ಮತ್ತು HTML5 ಜಿಪ್ ಪ್ಯಾಕೇಜ್‌ಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತೇವೆ. ಪ್ರಮಾಣಿತ ರೆಸಲ್ಯೂಶನ್ 1920×1080 (16:9 ಆಕಾರ ಅನುಪಾತ), ವೀಡಿಯೊ ಜಾಹೀರಾತುಗಳಿಗೆ ಗರಿಷ್ಠ ಅವಧಿ 30 ಸೆಕೆಂಡುಗಳು ಮತ್ತು ಫೈಲ್ ಗಾತ್ರವು 50 MB ಗಿಂತ ಕಡಿಮೆಯಿರಬೇಕು.',
  'advertiser_faq2_q': 'ಶಿಫಾರಸು ಮಾಡಲಾದ ಕ್ರಿಯೇಟಿವ್ ವಿಶೇಷಣಗಳು ಯಾವುವು?',
  'advertiser_faq3_a': 'ಪ್ರತಿಯೊಂದು ಅಭಿಯಾನವು ಟ್ರ್ಯಾಕ್ ಮಾಡಬಹುದಾದ QR ಗುರುತನ್ನು ಉತ್ಪಾದಿಸುತ್ತದೆ. ಪ್ರಯಾಣಿಕರು ಪರದೆಯ ಮೇಲೆ ಪ್ರದರ್ಶಿಸಲಾದ QR ಕೋಡ್ ಅನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿದಾಗ, ಸಿಸ್ಟಮ್ ಸಮಯ, ಸ್ಥಳ, ವಾಹನ ID ಅನ್ನು ದಾಖಲಿಸುತ್ತದೆ ಮತ್ತು ಅವರನ್ನು ನಿಮ್ಮ ಲ್ಯಾಂಡಿಂಗ್ ಪುಟಕ್ಕೆ ಮರುನಿರ್ದೇಶಿಸುತ್ತದೆ.',
  'advertiser_faq3_q': 'ಸ್ಮಾರ್ಟ್ QR ಕೋಡ್ ಲೀಡ್ ಗುಣಲಕ್ಷಣ ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ?',
  'advertiser_faq4_a': 'ಅಭಿಯಾನಗಳಿಗೆ ದೈನಂದಿನ ಅಥವಾ ಒಟ್ಟು ಬಜೆಟ್ ಮಾದರಿಯಲ್ಲಿ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುತ್ತದೆ. ಜಾಹೀರಾತು ವೆಚ್ಚದ ಮೇಲೆ GST (18%) ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ. ಪರಿಶೀಲನೆ ಅನುಮೋದನೆಯ ನಂತರ ತೆರಿಗೆ ಕ್ರೆಡಿಟ್‌ಗಳೊಂದಿಗೆ ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಉತ್ಪತ್ತಿಯಾಗುತ್ತವೆ.',
  'advertiser_faq4_q': 'ಬಿಲ್ಲಿಂಗ್, GST ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಮತ್ತು ಕಡಿತಗಳು ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆ?',
  'advertiser_growth_desk': 'ಜಾಹೀರಾತುದಾರರ ಬೆಳವಣಿಗೆಯ ಡೆಸ್ಕ್',
  'could_not_open_doc': 'ದಾಖಲೆ URL ತೆರೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ: @error',
  'faqs_accordion_sub': 'ಸಾಮಾನ್ಯ ಪರಿಹಾರಗಳು, ಕಾರ್ಯಾಚರಣೆಯ ಮಾರ್ಗಸೂಚಿಗಳು ಮತ್ತು ದೋಷನಿವಾರಣೆ ಸೂಚನೆಗಳು',
