  'video_tut2_desc': 'ವೀಡಿಯೊ ಫಾರ್ಮ್ಯಾಟಿಂಗ್ (1080p MP4), ಆಕಾರ ಅನುಪಾತಗಳು ಮತ್ತು ಸ್ವಯಂಚಾಲಿತ ಜಾಹೀರಾತು ಅನುಸರಣೆ ತಪಾಸಣೆಗಳಲ್ಲಿ ಉತ್ತೀರ್ಣರಾಗಲು ಕಲಿಯಿರಿ.',
