  'gov_help.faq1_a': 'ಪ್ರಸಾರ ಪ್ರಕಟಣೆಗಳಿಗೆ ಹೋಗಿ, "ತುರ್ತು ಎಚ್ಚರಿಕೆ" ಆಯ್ಕೆಮಾಡಿ, ಭೌಗೋಳಿಕ ವಲಯಗಳು ಅಥವಾ ಮಾರ್ಗಗಳನ್ನು ವಿವರಿಸಿ, ಎಚ್ಚರಿಕೆಯ ಅವಧಿಯನ್ನು ನಿಗದಿಪಡಿಸಿ ಮತ್ತು ನಿಮ್ಮ ದ್ವಿ-ಅಂಶ ದೃಢೀಕರಣ ಪಿನ್‌ನೊಂದಿಗೆ ದೃಢೀಕರಿಸಿ.',
