  'gov_help.faq2_a': 'ಎಲ್ಲಾ ಸಕ್ರಿಯ ಪುರಸಭೆಯ ಮಾರ್ಗಗಳಲ್ಲಿ ಪ್ರತಿ 60 ಸೆಕೆಂಡಿಗೆ ಜಿಪಿಎಸ್, ಸ್ಮಾರ್ಟ್ ಟಿಕೆಟಿಂಗ್ ಮತ್ತು ಸ್ಟಾಪ್ ಕ್ಯಾಮೆರಾ ಸಂವೇದಕಗಳಿಂದ ಪ್ರಯಾಣಿಕರ ಲೋಡ್ ಟೆಲಿಮೆಟ್ರಿಯನ್ನು ಒಟ್ಟುಗೂಡಿಸಲಾಗುತ್ತದೆ.',
  'gov_help.faq3_q': 'ರಾಜ್ಯ ಲೆಕ್ಕಪರಿಶೋಧನೆಗಾಗಿ ಶಾಸನಬದ್ಧ ಅನುಸರಣೆ ಲಾಗ್‌ಗಳನ್ನು ರಫ್ತು ಮಾಡುವುದು ಹೇಗೆ?',
  'gov_help.faq3_a': 'ಅನುಸರಣೆ ವರದಿಗಳಿಗೆ ನ್ಯಾವಿಗೇಟ್ ಮಾಡಿ, ಆಡಿಟ್ ದಿನಾಂಕ ಶ್ರೇಣಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಟ್ಯಾಂಪರ್-ಪ್ರೂಫ್ SHA-256 ಸಹಿ ಮಾಡಿದ CSV ಅಥವಾ PDF ಆಡಿಟ್ ಬಂಡಲ್‌ಗಳನ್ನು ರಫ್ತು ಮಾಡಿ.',
  'gov_help.faq4_q': 'ವಾಣಿಜ್ಯ ಜಾಹೀರಾತು ಪ್ರದರ್ಶನಗಳಿಗೆ ಅಗತ್ಯವಿರುವ ಸುರಕ್ಷತಾ ಮಾನದಂಡಗಳು ಯಾವುವು?',
  'gov_help.faq4_a': 'ಎಲ್ಲಾ ಸಾರಿಗೆ ಪ್ರದರ್ಶನಗಳು ರಾತ್ರಿ ಸಾರಿಗೆಯ ಸಮಯದಲ್ಲಿ ಕಡ್ಡಾಯ ಸ್ವಯಂ-ಮಬ್ಬಾಗಿಸುವಿಕೆಯೊಂದಿಗೆ ವಾಹನ ಕಂಪನ (ISO 16750) ಮತ್ತು ಜ್ವಾಲೆಯ-ನಿರೋಧಕ ಸುರಕ್ಷತಾ ಮಾನದಂಡಗಳಿಗೆ ಬದ್ಧವಾಗಿರುತ್ತವೆ.',
